const NODE_ELEMENT = 1;
const NODE_PI = 7;
const NODE_COMMENT = 8;
const SHOW_MARKERS = 0x80 | 0x40;
const MARKER_RE = /^\?(start|end|marker)(?=[\s?]|$)(.*?)\??$/s;
const ATTR_RE = /([^\s"'=<>/?]+)(?:\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s"'>]+)))?/g;
const TEMPLATE_TAG_RE = /<(\/?)template(?![\w-])(?:[^>"']|"[^"]*"|'[^']*')*>/gi;

const nativeSupport = new WeakMap();
const states = new WeakMap();

function parseFragment(html, doc) {
    const template = doc.createElement("template");
    if (typeof template.setHTMLUnsafe === "function") {
        template.setHTMLUnsafe(html);
    } else {
        template.innerHTML = html;
    }
    return template.content;
}

/**
 * Detects native declarative partial update support: `<?marker>` must parse
 * to a ProcessingInstruction (not a bogus comment) and
 * `Element.prototype.streamAppendHTMLUnsafe` must exist. Cached per document.
 */
export function supportsNativePatching(doc = document) {
    let supported = nativeSupport.get(doc);
    if (supported === undefined) {
        const probe = parseFragment('<?marker name="probe">', doc).firstChild;
        const ElementCtor = doc.defaultView?.Element ?? globalThis.Element;
        supported =
            probe?.nodeType === NODE_PI &&
            typeof ElementCtor?.prototype?.streamAppendHTMLUnsafe === "function";
        nativeSupport.set(doc, supported);
    }
    return supported;
}

/**
 * Parses a marker node (comment or ProcessingInstruction) into
 * `{ kind, name }`, or returns null if it is not a patch marker.
 * `name` is null when the marker has no name attribute (e.g. `<?end>`).
 * Browsers without support turn `<?start name="x">` into a comment with data
 * `?start name="x"`; a trailing `?` (from `?>`) is tolerated.
 */
export function parseMarker(node) {
    let kind;
    let attrs;
    if (node.nodeType === NODE_PI) {
        kind = node.target.toLowerCase();
        attrs = node.data.replace(/\?$/, "");
    } else if (node.nodeType === NODE_COMMENT) {
        const match = MARKER_RE.exec(node.data);
        if (!match) {
            return null;
        }
        kind = match[1].toLowerCase();
        attrs = match[2];
    } else {
        return null;
    }
    if (kind !== "start" && kind !== "end" && kind !== "marker") {
        return null;
    }
    let name = null;
    for (const m of attrs.matchAll(ATTR_RE)) {
        if (m[1].toLowerCase() === "name") {
            name = m[2] ?? m[3] ?? m[4] ?? "";
            break;
        }
    }
    return { kind, name };
}

function collectTargets(container, into) {
    const doc = container.ownerDocument ?? container;
    const walker = doc.createTreeWalker(container, SHOW_MARKERS);
    for (let node = walker.nextNode(); node; node = walker.nextNode()) {
        const info = parseMarker(node);
        if (info && info.kind !== "end" && info.name !== null && !into.has(info.name)) {
            into.set(info.name, node);
        }
    }
}

function getState(root) {
    let state = states.get(root);
    if (!state) {
        const doc = root.ownerDocument ?? root;
        const Observer = doc.defaultView?.MutationObserver ?? globalThis.MutationObserver;
        const observer = new Observer(() => {});
        observer.observe(root, { childList: true, subtree: true });
        state = { observer, index: null };
        states.set(root, state);
    }
    return state;
}

/**
 * Returns the name -> marker node index for `root`, rebuilding it only if
 * the tree changed since it was built (pending mutation records are checked
 * synchronously so back-to-back patches see each other's effects).
 */
function getIndex(root) {
    const state = getState(root);
    if (state.observer.takeRecords().length) {
        state.index = null;
    }
    if (!state.index) {
        state.index = new Map();
        collectTargets(root, state.index);
    }
    return state.index;
}

function findTarget(root, name) {
    const index = getIndex(root);
    const node = index.get(name);
    if (node && !root.contains(node)) {
        getState(root).index = null;
        return findTarget(root, name);
    }
    return node ?? null;
}

function findEnd(start) {
    let depth = 0;
    for (let node = start.nextSibling; node; node = node.nextSibling) {
        const info = parseMarker(node);
        if (info?.kind === "start") {
            depth++;
        } else if (info?.kind === "end") {
            if (depth === 0) {
                return node;
            }
            depth--;
        }
    }
    return null;
}

function forgetMarkers(index, removed) {
    const gone = new Set();
    const note = node => {
        gone.add(node);
        for (const child of node.childNodes) {
            note(child);
        }
    };
    removed.forEach(note);
    for (const [name, node] of index) {
        if (gone.has(node)) {
            index.delete(name);
        }
    }
}

function applyManually(root, target, info, mode, content) {
    const parent = target.parentNode;
    const added = Array.from(content.childNodes);
    let anchor = target;
    const removed = [];
    if (info.kind === "start") {
        anchor = findEnd(target);
        if (mode === "replace") {
            for (let n = target.nextSibling; n && n !== anchor; n = n.nextSibling) {
                removed.push(n);
            }
            removed.forEach(n => n.remove());
        }
    }
    parent.insertBefore(content, anchor);
    // As natively, the target's markers go once the patch is applied; a patch
    // that wants to stay appendable re-emits its marker.
    target.remove();
    removed.push(target);
    if (anchor && anchor !== target) {
        anchor.remove();
        removed.push(anchor);
    }

    const state = getState(root);
    state.observer.takeRecords();
    if (state.index) {
        forgetMarkers(state.index, removed);
        const fresh = new Map();
        for (const node of added) {
            if (node.nodeType === NODE_ELEMENT) {
                collectTargets(node, fresh);
            }
            const marker = parseMarker(node);
            if (marker && marker.kind !== "end" && marker.name !== null && !fresh.has(marker.name)) {
                fresh.set(marker.name, node);
            }
        }
        for (const [name, node] of fresh) {
            if (!state.index.has(name)) {
                state.index.set(name, node);
            }
        }
    }
}

// Native application is asynchronous: the returned promise settles once the
// browser has applied the patch.
function applyNatively(target, template) {
    const writer = target.parentNode.streamAppendHTMLUnsafe().getWriter();
    return Promise.all([writer.write(template.outerHTML), writer.close()]);
}

function attachUnmatched(doc, template) {
    template.setAttribute("data-patch-unmatched", "");
    (doc.body ?? doc.documentElement).append(template);
}

/**
 * Applies every top-level `<template for="NAME" data-patch-mode="replace|append">`
 * in `html` to the matching `<?start>`/`<?marker>` target in `root`.
 * Unmatched templates are attached to the body with `data-patch-unmatched`.
 * Returns `{ name, mode, applied }` per template. Native application is
 * asynchronous; use applyPatchHTMLAndWait to know when it has happened.
 */
export function applyPatchHTML(html, root = document) {
    return applyPatches(html, root).results;
}

/**
 * Like applyPatchHTML, but resolves with the results once every patch has
 * been applied.
 */
export async function applyPatchHTMLAndWait(html, root = document) {
    const { results, applying } = applyPatches(html, root);
    await Promise.all(applying);
    return results;
}

function applyPatches(html, root) {
    const doc = root.ownerDocument ?? root;
    const fragment = parseFragment(html, doc);
    const native = supportsNativePatching(doc);
    const results = [];
    const applying = [];
    for (const template of Array.from(fragment.childNodes)) {
        if (template.nodeType !== NODE_ELEMENT || template.localName !== "template" || !template.hasAttribute("for")) {
            continue;
        }
        const name = template.getAttribute("for");
        const mode = template.getAttribute("data-patch-mode") === "append" ? "append" : "replace";
        const target = findTarget(root, name);
        const info = target && parseMarker(target);
        if (!info) {
            attachUnmatched(doc, template);
            results.push({ name, mode, applied: false });
            continue;
        }
        if (native) {
            applying.push(applyNatively(target, template));
        } else {
            applyManually(root, target, info, mode, template.content);
        }
        results.push({ name, mode, applied: true });
    }
    return { results, applying };
}

/**
 * Returns `{ write(chunk), close() }`. Chunks are buffered and each complete
 * top-level `<template>` element is applied as soon as its closing tag
 * arrives. Both methods return the results of the patches applied by that call.
 */
export function createPatchStreamApplier(root = document) {
    let buffer = "";

    const drain = () => {
        const results = [];
        let depth = 0;
        let start = -1;
        let consumed = 0;
        TEMPLATE_TAG_RE.lastIndex = 0;
        for (let m = TEMPLATE_TAG_RE.exec(buffer); m; m = TEMPLATE_TAG_RE.exec(buffer)) {
            if (m[1]) {
                if (depth > 0 && --depth === 0) {
                    const end = m.index + m[0].length;
                    results.push(...applyPatchHTML(buffer.slice(start, end), root));
                    consumed = end;
                }
            } else if (depth++ === 0) {
                start = m.index;
            }
        }
        buffer = depth === 0 ? buffer.slice(consumed) : buffer.slice(start);
        return results;
    };

    return {
        write(chunk) {
            buffer += chunk;
            return drain();
        },
        close() {
            const results = drain();
            if (buffer.includes("<template")) {
                results.push(...applyPatchHTML(buffer, root));
            }
            buffer = "";
            return results;
        },
    };
}
